<!doctype html>
<html lang="zh-CN">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>A、B 两车追及问题 · 交互可视化</title>
<style>
:root{
  --bg:#eef2f9; --card:#fff; --ink:#1e293b; --muted:#64748b;
  --line:#e2e8f2; --ca:#2563eb; --cb:#ea580c; --cg:#059669; --cr:#dc2626;
}
*{box-sizing:border-box}
html,body{margin:0;padding:0}
body{
  background:var(--bg); color:var(--ink);
  font-family:"PingFang SC","Microsoft YaHei","Helvetica Neue",Arial,system-ui,sans-serif;
  font-size:14px; line-height:1.65; -webkit-font-smoothing:antialiased;
}
.wrap{max-width:1180px;margin:0 auto;padding:20px 16px 64px}
h1{font-size:21px;margin:0 0 6px;letter-spacing:.3px}
.lead{margin:0;color:var(--muted);font-size:13px}
.given{display:flex;flex-wrap:wrap;gap:8px;margin:12px 0 16px}
.chip{background:#fff;border:1px solid var(--line);border-radius:999px;padding:5px 13px;
  font-size:12.5px;color:#334155;box-shadow:0 1px 2px rgba(15,23,42,.05);white-space:nowrap}
.chip b.a{color:var(--ca)} .chip b.b{color:var(--cb)}
.card{background:var(--card);border:1px solid var(--line);border-radius:14px;
  padding:14px 16px 16px;box-shadow:0 2px 10px rgba(15,23,42,.05);margin-bottom:14px}
.card-head{display:flex;align-items:center;gap:8px;margin-bottom:10px;flex-wrap:wrap}
.card-head h2{font-size:14.5px;margin:0;font-weight:700}
.badge{margin-left:auto;font-size:12px;color:var(--muted);background:#f1f5fb;
  border-radius:8px;padding:2px 10px;font-variant-numeric:tabular-nums}
svg#road{width:100%;height:auto;display:block;border-radius:10px;background:#f8fafd}
.readouts{display:grid;grid-template-columns:1fr 1fr 1fr;gap:8px;margin-top:10px}
@media(max-width:640px){.readouts{grid-template-columns:1fr}}
.ro{background:#f7f9fd;border:1px solid #edf1f8;border-radius:10px;padding:7px 11px}
.ro .k{font-size:11.5px;color:var(--muted)}
.ro .v{font-size:13.5px;font-weight:600;font-variant-numeric:tabular-nums}
.ro.a .v{color:var(--ca)} .ro.b .v{color:var(--cb)} .ro.g .v{color:var(--cg)}
.grid2{display:grid;grid-template-columns:1fr 1fr;gap:14px}
@media(max-width:900px){.grid2{grid-template-columns:1fr}}
canvas.chart{width:100%;height:300px;display:block}
@media(max-width:640px){canvas.chart{height:245px}}

.ctl-row{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-bottom:10px}
.btn{border:1px solid #cbd5e1;background:#fff;color:#334155;border-radius:9px;
  padding:7px 16px;font-size:13px;font-family:inherit;cursor:pointer;transition:.15s;font-weight:600}
.btn:hover{background:#f1f5fb;border-color:#94a3b8}
.btn.primary{background:var(--ca);border-color:var(--ca);color:#fff}
.btn.primary:hover{background:#1d4ed8}
.btn:disabled{opacity:.45;cursor:default}
.time-show{margin-left:auto;font-size:13px;color:var(--muted);font-variant-numeric:tabular-nums}
.time-show b{color:#0f172a;font-size:15px}

input[type=range]{width:100%;-webkit-appearance:none;appearance:none;height:6px;border-radius:3px;
  background:linear-gradient(90deg,#93c5fd,#bcd3f7);outline:none;margin:6px 0 2px;cursor:pointer}
input[type=range]::-webkit-slider-thumb{-webkit-appearance:none;appearance:none;width:18px;height:18px;
  border-radius:50%;background:#2563eb;border:3px solid #fff;box-shadow:0 1px 4px rgba(0,0,0,.25);cursor:pointer}
input[type=range]::-moz-range-thumb{width:18px;height:18px;border-radius:50%;background:#2563eb;
  border:3px solid #fff;box-shadow:0 1px 4px rgba(0,0,0,.25);cursor:pointer}
.ticks{display:flex;justify-content:space-between;font-size:11px;color:#94a3b8;
  font-variant-numeric:tabular-nums;padding:0 2px;margin-top:2px}

.step-nav{display:flex;align-items:center;gap:10px;margin-bottom:10px;flex-wrap:wrap}
.step-label{font-size:12.5px;color:var(--muted);margin-left:auto;font-variant-numeric:tabular-nums}
.step-title{font-size:15px;font-weight:700;margin:0 0 6px;color:#0f172a}
.step-body{font-size:13.5px;color:#3b4a60;margin:0 0 10px}
.formula{background:#f5f8fd;border:1px dashed #c9d8ef;border-radius:10px;
  padding:10px 14px;font-size:14px;color:#0f172a;letter-spacing:.2px;overflow-x:auto;white-space:nowrap}
.formula b{color:var(--cg);font-size:15px}

.p3-status{margin-top:10px;padding:9px 13px;border-radius:10px;font-size:13.5px;font-weight:600;
  background:#f1f5fb;color:#334155;border:1px solid #e2e8f2}
.p3-status.two{background:#ecfdf5;color:#047857;border-color:#a7f3d0}
.p3-status.one{background:#fffbeb;color:#b45309;border-color:#fde68a}
.p3-status.zero{background:#fef2f2;color:#b91c1c;border-color:#fecaca}
.foot{color:#94a3b8;font-size:12px;text-align:center;margin-top:22px}
</style>
</head>
<body>
<div class="wrap">

  <h1>A、B 两车追及问题</h1>
  <p class="lead">同向行驶 · 匀变速直线运动 · 用「位置–时间图」和「速度–时间图」看清间距的变化</p>
  <div class="given">
    <div class="chip"><b class="a">A 车（在前）</b> v₀ = 16 m/s，a = −2 m/s²</div>
    <div class="chip"><b class="b">B 车（在后）</b> v₀ = 4 m/s，a = +1 m/s²</div>
    <div class="chip">初始间距 x₀ = 56 m</div>
  </div>

  <!-- ===== 场景 ===== -->
  <section class="card">
    <div class="card-head">
      <h2>两车位置（俯视）</h2>
      <span class="badge" id="timeBadge">t = 0.00 s</span>
    </div>
    <svg id="road" viewBox="0 0 900 200" aria-label="两车位置示意图"></svg>
    <div class="readouts">
      <div class="ro a"><div class="k">A 车</div><div class="v" id="roA">x = 56.0 m ， v = 16.0 m/s</div></div>
      <div class="ro g"><div class="k">两车间距</div><div class="v" id="roGap">56.0 m</div></div>
      <div class="ro b"><div class="k">B 车</div><div class="v" id="roB">x = 0.0 m ， v = 4.0 m/s</div></div>
    </div>
  </section>

  <!-- ===== 控制 ===== -->
  <section class="card">
    <div class="ctl-row">
      <button class="btn primary" id="playBtn">播放</button>
      <button class="btn" id="resetBtn">回到 t = 0</button>
      <div class="time-show">t = <b id="tVal">0.00</b> s</div>
    </div>
    <input type="range" id="tSlider" min="0" max="14" step="0.02" value="0" aria-label="时间滑块">
    <div class="ticks">
      <span>0</span><span>2</span><span>4</span><span>6</span><span>8</span><span>10</span><span>12</span><span>14</span>
    </div>
  </section>

  <!-- ===== 两张图 ===== -->
  <div class="grid2">
    <section class="card">
      <div class="card-head"><h2>位置–时间图</h2></div>
      <canvas id="xt" class="chart"></canvas>
    </section>
    <section class="card">
      <div class="card-head"><h2>速度–时间图</h2></div>
      <canvas id="vt" class="chart"></canvas>
    </section>
  </div>

  <!-- ===== 步骤 ===== -->
  <section class="card">
    <div class="step-nav">
      <button class="btn" id="prevStep">上一步</button>
      <button class="btn primary" id="nextStep">下一步</button>
      <span class="step-label" id="stepLabel">1 / 6</span>
    </div>
    <h3 class="step-title" id="stepTitle"></h3>
    <p class="step-body" id="stepBody"></p>
    <div class="formula" id="stepFormula"></div>
  </section>

  <!-- ===== 第三问 ===== -->
  <section class="card">
    <div class="card-head">
      <h2>第（3）问 · 若 A 在后、B 在前，初始间距 x₀ 取什么值会相遇两次？</h2>
    </div>
    <canvas id="p3chart" class="chart" style="height:285px"></canvas>
    <div class="ctl-row" style="margin-top:12px">
      <span style="font-size:13px;color:#475569">x₀ = <b id="x0Val" style="color:#0f172a;font-size:15px">18</b> m</span>
      <input type="range" id="x0Slider" min="0" max="40" step="0.5" value="18"
             style="flex:1;min-width:180px" aria-label="初始间距滑块">
    </div>
    <div class="p3-status" id="p3Status"></div>
  </section>

  <p class="foot">拖动滑块 / 播放动画，观察两条曲线的高度差如何变化</p>
</div>

<script>
(function(){
  'use strict';

  /* ================= 物理模型 ================= */
  var T_STOP = 8;     // A 车停下时刻
  var T_MAX  = 14;    // 时间轴上限

  function posA(t){ var tt = Math.min(t, T_STOP); return 56 + 16*tt - tt*tt; }
  function velA(t){ return Math.max(0, 16 - 2*t); }
  function posB(t){ return 4*t + 0.5*t*t; }
  function velB(t){ return 4 + t; }

  var state = { t:0, playing:false, step:0, x0:18 };

  /* ================= 画布工具 ================= */
  var cache = new WeakMap();
  function fitCanvas(cv){
    var dpr = Math.min(window.devicePixelRatio || 1, 2);
    var rect = cv.getBoundingClientRect();
    var w = Math.max(rect.width || 300, 120);
    var h = Math.max(rect.height || 240, 120);
    var c = cache.get(cv);
    if (!c || c.w !== w || c.h !== h){
      cv.width  = Math.round(w*dpr);
      cv.height = Math.round(h*dpr);
      c = { w:w, h:h, ctx:cv.getContext('2d'), dpr:dpr };
      cache.set(cv, c);
    }
    c.ctx.setTransform(dpr,0,0,dpr,0,0);
    return c;
  }
  function line(ctx,x1,y1,x2,y2){ ctx.beginPath(); ctx.moveTo(x1,y1); ctx.lineTo(x2,y2); ctx.stroke(); }

  /* ================= 道路场景 ================= */
  var ORIGIN = 60, SCALE = 5;

  function buildRoad(){
    var svg = document.getElementById('road');
    var s = '';
    s += '<defs><linearGradient id="rg" x1="0" y1="0" x2="0" y2="1">'
       + '<stop offset="0" stop-color="#e6edf7"/><stop offset="1" stop-color="#cbd7e8"/></linearGradient></defs>';
    s += '<rect x="0" y="132" width="900" height="68" fill="url(#rg)"/>';
    s += '<line x1="0" y1="132" x2="900" y2="132" stroke="#b3c1d6" stroke-width="2"/>';
    for (var m=0; m<=160; m+=20){
      var px = ORIGIN + m*SCALE;
      s += '<line x1="'+px+'" y1="132" x2="'+px+'" y2="140" stroke="#a3b3c9" stroke-width="1"/>';
      s += '<text x="'+px+'" y="155" font-size="11" fill="#8698b1" text-anchor="middle">'+m+'</text>';
    }
    s += '<text x="892" y="155" font-size="11" fill="#8698b1" text-anchor="end">位置 / m</text>';
    // 间距标注
    s += '<g id="gapGroup" opacity="0">'
       + '<line id="gapLine" x1="0" y1="180" x2="0" y2="180" stroke="#059669" stroke-width="2"/>'
       + '<line id="gapT1" x1="0" y1="174" x2="0" y2="186" stroke="#059669" stroke-width="2"/>'
       + '<line id="gapT2" x1="0" y1="174" x2="0" y2="186" stroke="#059669" stroke-width="2"/>'
       + '<text id="gapText" x="0" y="200" font-size="12" font-weight="700" fill="#059669" text-anchor="middle"></text>'
       + '</g>';
    // 车辆
    s += '<g id="carB" transform="translate(60,132)">'
       + '<text x="0" y="-46" text-anchor="middle" font-size="14" font-weight="800" fill="#ea580c">B</text>'
       + '<rect x="-9" y="-40" width="18" height="13" rx="4" fill="#fb923c"/>'
       + '<rect x="-14" y="-31" width="28" height="19" rx="6" fill="#ea580c"/>'
       + '<circle cx="-7.5" cy="-4" r="4.5" fill="#334155"/>'
       + '<circle cx="7.5" cy="-4" r="4.5" fill="#334155"/>'
       + '</g>';
    s += '<g id="carA" transform="translate(340,132)">'
       + '<text x="0" y="-46" text-anchor="middle" font-size="14" font-weight="800" fill="#2563eb">A</text>'
       + '<rect x="-9" y="-40" width="18" height="13" rx="4" fill="#60a5fa"/>'
       + '<rect x="-14" y="-31" width="28" height="19" rx="6" fill="#2563eb"/>'
       + '<circle cx="-7.5" cy="-4" r="4.5" fill="#334155"/>'
       + '<circle cx="7.5" cy="-4" r="4.5" fill="#334155"/>'
