  function updateScene(t){
    var xa = posA(t), xb = posB(t);
    var pa = ORIGIN + xa*SCALE, pb = ORIGIN + xb*SCALE;
    var carA = document.getElementById('carA');
    var carB = document.getElementById('carB');
    if (carA) carA.setAttribute('transform','translate('+pa.toFixed(1)+',132)');
    if (carB) carB.setAttribute('transform','translate('+pb.toFixed(1)+',132)');

    var g = document.getElementById('gapGroup');
    if (!g) return;
    var d = xa - xb;
    var ad = Math.abs(d);
    if (ad < 2.2){ g.setAttribute('opacity','0'); return; }
    g.setAttribute('opacity','1');
    var l = Math.min(pa,pb), r = Math.max(pa,pb), y = 180;
    var L1 = document.getElementById('gapLine');
    var L2 = document.getElementById('gapT1');
    var L3 = document.getElementById('gapT2');
    var TX = document.getElementById('gapText');
    L1.setAttribute('x1',l); L1.setAttribute('x2',r);
    L1.setAttribute('y1',y); L1.setAttribute('y2',y);
    L2.setAttribute('x1',l); L2.setAttribute('x2',l);
    L3.setAttribute('x1',r); L3.setAttribute('x2',r);
    TX.setAttribute('x',(l+r)/2);
    TX.textContent = ad.toFixed(0)+' m';
  }

  function updateReadouts(t){
    var xa = posA(t), xb = posB(t);
    var va = velA(t), vb = velB(t);
    document.getElementById('roA').textContent = 'x = '+xa.toFixed(1)+' m ， v = '+va.toFixed(1)+' m/s';
    document.getElementById('roB').textContent = 'x = '+xb.toFixed(1)+' m ， v = '+vb.toFixed(1)+' m/s';
    document.getElementById('roGap').textContent = Math.abs(xa-xb).toFixed(1)+' m';
    document.getElementById('timeBadge').textContent = 't = '+t.toFixed(2)+' s';
    document.getElementById('tVal').textContent = t.toFixed(2);
  }

  /* ================= 位置–时间图 ================= */
  function drawXT(){
    var cv = document.getElementById('xt');
    var o = fitCanvas(cv), ctx = o.ctx, w = o.w, h = o.h;
    var P = { l:52, r:24, t:20, b:38 };
    var pw = w-P.l-P.r, ph = h-P.t-P.b;
    var MAXT = 14, MAXX = 165;
    function X(t){ return P.l + t/MAXT*pw; }
    function Y(x){ return P.t + ph - x/MAXX*ph; }

    ctx.clearRect(0,0,w,h);

    // 网格
    ctx.strokeStyle='#e9eff8'; ctx.lineWidth=1;
    for (var t=0;t<=MAXT;t+=2) line(ctx, X(t), P.t, X(t), P.t+ph);
    for (var x=0;x<=160;x+=40) line(ctx, P.l, Y(x), P.l+pw, Y(x));

    // 坐标轴
    ctx.strokeStyle='#a9b6ca'; ctx.lineWidth=1.4;
    ctx.beginPath(); ctx.moveTo(P.l,P.t); ctx.lineTo(P.l,P.t+ph); ctx.lineTo(P.l+pw,P.t+ph); ctx.stroke();

    // 刻度
    ctx.fillStyle='#7c8da4'; ctx.font='11.5px system-ui,-apple-system,sans-serif';
    ctx.textAlign='center'; ctx.textBaseline='top';
    for (var t2=0;t2<=MAXT;t2+=2) ctx.fillText(String(t2), X(t2), P.t+ph+7);
    ctx.textAlign='right'; ctx.textBaseline='middle';
    for (var x2=0;x2<=160;x2+=40) ctx.fillText(String(x2), P.l-8, Y(x2));

    ctx.fillStyle='#95a4ba'; ctx.font='12px system-ui,-apple-system,sans-serif';
    ctx.textAlign='center'; ctx.textBaseline='alphabetic';
    ctx.fillText('时间 t / s', P.l+pw/2, h-8);
    ctx.save(); ctx.translate(13, P.t+ph/2); ctx.rotate(-Math.PI/2);
    ctx.textAlign='center'; ctx.fillText('位置 x / m', 0, 0); ctx.restore();

    // 曲线
    function curve(fn, color){
      ctx.beginPath(); ctx.strokeStyle=color; ctx.lineWidth=2.8;
      ctx.lineJoin='round'; ctx.lineCap='round';
      var N=260;
      for (var i=0;i<=N;i++){
        var tt = MAXT*i/N, px = X(tt), py = Y(fn(tt));
        if (i) ctx.lineTo(px,py); else ctx.moveTo(px,py);
      }
      ctx.stroke();
    }
    curve(posA, '#2563eb');
    curve(posB, '#ea580c');

    // 曲线名
    ctx.font='bold 13px system-ui,-apple-system,sans-serif';
    ctx.textAlign='left'; ctx.textBaseline='middle';
    ctx.fillStyle='#2563eb'; ctx.fillText('A', X(0.7), Y(posA(0.7))-14);
    ctx.fillStyle='#ea580c'; ctx.fillText('B', X(0.7), Y(posB(0.7))+18);

    // 当前时刻
    var t3 = state.t;
    ctx.setLineDash([5,5]); ctx.strokeStyle='#c0cde0'; ctx.lineWidth=1.2;
    line(ctx, X(t3), P.t, X(t3), P.t+ph);
    ctx.setLineDash([]);

    var xa = posA(t3), xb = posB(t3);
    var gap = xa - xb;

    // 间距箭头
    if (Math.abs(gap) > 1.5){
      ctx.strokeStyle='#059669'; ctx.lineWidth=2.2;
      line(ctx, X(t3), Y(xa), X(t3), Y(xb));
      // 端帽
      line(ctx, X(t3)-5, Y(xa), X(t3)+5, Y(xa));
      line(ctx, X(t3)-5, Y(xb), X(t3)+5, Y(xb));
      var right = X(t3) < P.l + pw*0.68;
      ctx.fillStyle='#059669';
      ctx.font='bold 12.5px system-ui,-apple-system,sans-serif';
      ctx.textAlign = right ? 'left' : 'right';
      ctx.textBaseline='middle';
      ctx.fillText(Math.abs(gap).toFixed(0)+' m', X(t3) + (right?9:-9), (Y(xa)+Y(xb))/2);
    }

    // 两个点
    ctx.fillStyle='#2563eb';
    ctx.beginPath(); ctx.arc(X(t3), Y(xa), 4.5, 0, Math.PI*2); ctx.fill();
    ctx.fillStyle='#ea580c';
    ctx.beginPath(); ctx.arc(X(t3), Y(xb), 4.5, 0, Math.PI*2); ctx.fill();

    // 相遇点
    if (state.step >= 4){
      var ix = 12, iy = 120;
      ctx.beginPath(); ctx.arc(X(ix), Y(iy), 6.5, 0, Math.PI*2);
      ctx.fillStyle='#059669'; ctx.fill();
      ctx.strokeStyle='#ffffff'; ctx.lineWidth=2.5; ctx.stroke();
      ctx.fillStyle='#047857';
      ctx.font='bold 12px system-ui,-apple-system,sans-serif';
      var al = 'center', tx = X(ix);
      if (X(ix) > P.l + pw*0.72){ al='right'; tx = X(ix)-10; } else { tx = X(ix)+10; al='left'; }
      ctx.textAlign=al; ctx.textBaseline='middle';
      ctx.fillText('t = 12 s，两车相遇', tx, Y(iy)-16);
    }
  }

  /* ================= 速度–时间图 ================= */
  function drawVT(){
    var cv = document.getElementById('vt');
    var o = fitCanvas(cv), ctx = o.ctx, w = o.w, h = o.h;
    var P = { l:52, r:24, t:20, b:38 };
    var pw = w-P.l-P.r, ph = h-P.t-P.b;
    var MAXT = 14, MAXV = 20;
    function X(t){ return P.l + t/MAXT*pw; }
    function Y(v){ return P.t + ph - v/MAXV*ph; }

    ctx.clearRect(0,0,w,h);

    // 网格
    ctx.strokeStyle='#e9eff8'; ctx.lineWidth=1;
    for (var t=0;t<=MAXT;t+=2) line(ctx, X(t), P.t, X(t), P.t+ph);
    for (var v=0;v<=20;v+=4) line(ctx, P.l, Y(v), P.l+pw, Y(v));

    // 速度差的阴影面积
    var tEnd = state.t;
    if (tEnd > 0.03){
      var N = 170;
      for (var i=0;i<N;i++){
        var ta = tEnd*i/N, tb = tEnd*(i+1)/N;
        var a1 = velA(ta), a2 = velA(tb), b1 = velB(ta), b2 = velB(tb);
        ctx.beginPath();
        ctx.moveTo(X(ta),Y(a1)); ctx.lineTo(X(tb),Y(a2));
        ctx.lineTo(X(tb),Y(b2)); ctx.lineTo(X(ta),Y(b1));
        ctx.closePath();
        ctx.fillStyle = ((a1-b1)+(a2-b2)) >= 0 ? 'rgba(5,150,105,0.20)' : 'rgba(220,38,38,0.16)';
        ctx.fill();
      }
    }

    // 坐标轴
    ctx.strokeStyle='#a9b6ca'; ctx.lineWidth=1.4;
    ctx.beginPath(); ctx.moveTo(P.l,P.t); ctx.lineTo(P.l,P.t+ph); ctx.lineTo(P.l+pw,P.t+ph); ctx.stroke();

    // 刻度
    ctx.fillStyle='#7c8da4'; ctx.font='11.5px system-ui,-apple-system,sans-serif';
    ctx.textAlign='center'; ctx.textBaseline='top';
    for (var t2=0;t2<=MAXT;t2+=2) ctx.fillText(String(t2), X(t2), P.t+ph+7);
    ctx.textAlign='right'; ctx.textBaseline='middle';
    for (var v2=0;v2<=20;v2+=4) ctx.fillText(String(v2), P.l-8, Y(v2));

    ctx.fillStyle='#95a4ba'; ctx.font='12px system-ui,-apple-system,sans-serif';
    ctx.textAlign='center'; ctx.textBaseline='alphabetic';
    ctx.fillText('时间 t / s', P.l+pw/2, h-8);
    ctx.save(); ctx.translate(13, P.t+ph/2); ctx.rotate(-Math.PI/2);
    ctx.textAlign='center'; ctx.fillText('速度 v / (m·s⁻¹)', 0, 0); ctx.restore();

    // 速度曲线
    function curve(fn, color){
      ctx.beginPath(); ctx.strokeStyle=color; ctx.lineWidth=2.8; ctx.lineJoin='round'; ctx.lineCap='round';
      var N=260;
      for (var i=0;i<=N;i++){
        var tt = MAXT*i/N, px = X(tt), py = Y(fn(tt));
        if (i) ctx.lineTo(px,py); else ctx.moveTo(px,py);
      }
      ctx.stroke();
    }
    curve(velA, '#2563eb');
    curve(velB, '#ea580c');

    ctx.font='bold 13px system-ui,-apple-system,sans-serif';
    ctx.textAlign='left'; ctx.textBaseline='middle';
    ctx.fillStyle='#2563eb'; ctx.fillText('A', X(1.6), Y(velA(1.6))-15);
    ctx.fillStyle='#ea580c'; ctx.fillText('B', X(1.6), Y(velB(1.6))+19);

    // 速度相等点
    if (state.step >= 2){
      ctx.beginPath(); ctx.arc(X(4), Y(8), 6, 0, Math.PI*2);
      ctx.fillStyle='#334155'; ctx.fill();
      ctx.strokeStyle='#fff'; ctx.lineWidth=2.5; ctx.stroke();
      ctx.setLineDash([4,4]); ctx.strokeStyle='#94a3b8'; ctx.lineWidth=1.2;
      line(ctx, X(4), Y(8), X(4), P.t+ph);
      ctx.setLineDash([]);
      ctx.fillStyle='#334155'; ctx.font='bold 12px system-ui,-apple-system,sans-serif';
      ctx.textAlign='center'; ctx.textBaseline='bottom';
      ctx.fillText('vA = vB = 8 m/s ， t = 4 s', X(4), Y(8)-14);
    }

    // 当前时刻竖线
    var t3 = state.t;
    ctx.setLineDash([5,5]); ctx.strokeStyle='#c0cde0'; ctx.lineWidth=1.2;
    line(ctx, X(t3), P.t, X(t3), P.t+ph);
    ctx.setLineDash([]);
    ctx.fillStyle='#2563eb';
    ctx.beginPath(); ctx.arc(X(t3), Y(velA(t3)), 4.5, 0, Math.PI*2); ctx.fill();
    ctx.fillStyle='#ea580c';
    ctx.beginPath(); ctx.arc(X(t3), Y(velB(t3)), 4.5, 0, Math.PI*2); ctx.fill();
  }

  /* ================= 第三问：间距–时间图 ================= */
  function d3(t, x0){
    if (t <= T_STOP) return x0 - 12*t + 1.5*t*t;
    return x0 + 64 - 4*t - 0.5*t*t;
  }

  function drawPart3(){
    var cv = document.getElementById('p3chart');
    var o = fitCanvas(cv), ctx = o.ctx, w = o.w, h = o.h;
    var P = { l:54, r:26, t:22, b:38 };
    var pw = w-P.l-P.r, ph = h-P.t-P.b;
    var MAXT = 8.5, YMIN = -28, YMAX = 42;
    function X(t){ return P.l + t/MAXT*pw; }
    function Y(d){ return P.t + ph - (d-YMIN)/(YMAX-YMIN)*ph; }

    var x0 = state.x0;

    ctx.clearRect(0,0,w,h);

    // 网格
    ctx.strokeStyle='#e9eff8'; ctx.lineWidth=1;
    for (var t=0;t<=8;t+=1) line(ctx, X(t), P.t, X(t), P.t+ph);
    for (var d=-20;d<=40;d+=20) line(ctx, P.l, Y(d), P.l+pw, Y(d));

    // 零线（两车同位置）
    ctx.strokeStyle='#94a3b8'; ctx.lineWidth=1.6;
    line(ctx, P.l, Y(0), P.l+pw, Y(0));
    ctx.fillStyle='#94a3b8'; ctx.font='11.5px system-ui,-apple-system,sans-serif';
    ctx.textAlign='left'; ctx.textBaseline='bottom';
    ctx.fillText('间距 = 0（相遇）', P.l+6, Y(0)-4);

    // 坐标轴
    ctx.strokeStyle='#a9b6ca'; ctx.lineWidth=1.4;
    ctx.beginPath(); ctx.moveTo(P.l,P.t); ctx.lineTo(P.l,P.t+ph); ctx.lineTo(P.l+pw,P.t+ph); ctx.stroke();

    ctx.fillStyle='#7c8da4'; ctx.font='11.5px system-ui,-apple-system,sans-serif';
    ctx.textAlign='center'; ctx.textBaseline='top';
    for (var t2=0;t2<=8;t2+=1) ctx.fillText(String(t2), X(t2), P.t+ph+7);
    ctx.textAlign='right'; ctx.textBaseline='middle';
    [-20,0,20,40].forEach(function(dd){ ctx.fillText(String(dd), P.l-8, Y(dd)); });

    ctx.fillStyle='#95a4ba'; ctx.font='12px system-ui,-apple-system,sans-serif';
    ctx.textAlign='center'; ctx.textBaseline='alphabetic';
    ctx.fillText('时间 t / s', P.l+pw/2, h-8);
    ctx.save(); ctx.translate(13, P.t+ph/2); ctx.rotate(-Math.PI/2);
    ctx.textAlign='center'; ctx.fillText('间距 d / m', 0, 0); ctx.restore();

    // 间距曲线
    ctx.beginPath(); ctx.strokeStyle='#7c3aed'; ctx.lineWidth=2.9;
    ctx.lineJoin='round'; ctx.lineCap='round';
    var N = 300;
    for (var i=0;i<=N;i++){
      var tt = MAXT*i/N, px = X(tt), py = Y(d3(tt,x0));
      if (i) ctx.lineTo(px,py); else ctx.moveTo(px,py);
    }
    ctx.stroke();

    // 最小值点
    var dmin = x0 - 24;
    ctx.setLineDash([4,4]); ctx.strokeStyle='#c4b5fd'; ctx.lineWidth=1.2;
    line(ctx, X(4), Y(dmin), X(4), Y(0));
    ctx.setLineDash([]);
    ctx.beginPath(); ctx.arc(X(4), Y(dmin), 4.5, 0, Math.PI*2);
    ctx.fillStyle='#7c3aed'; ctx.fill();
    ctx.fillStyle='#6d28d9'; ctx.font='bold 11.5px system-ui,-apple-system,sans-serif';
    ctx.textAlign='center'; ctx.textBaseline='bottom';
    ctx.fillText('最小值 x₀−24', X(4), Y(dmin)-10);

    // 交点
    var disc = 144 - 6*x0;
    if (disc >= 0){
      var sq = Math.sqrt(disc);
      var roots = [ (12-sq)/3, (12+sq)/3 ];
      var uniq = (sq < 1e-6) ? [4] : roots;
      for (var k=0;k<uniq.length;k++){
        ctx.beginPath(); ctx.arc(X(uniq[k]), Y(0), 6, 0, Math.PI*2);
        ctx.fillStyle='#059669'; ctx.fill();
        ctx.strokeStyle='#fff'; ctx.lineWidth=2.4; ctx.stroke();
        ctx.fillStyle='#047857'; ctx.font='bold 11.5px system-ui,-apple-system,sans-serif';
        ctx.textAlign='center'; ctx.textBaseline='bottom';
        ctx.fillText('t = '+uniq[k].toFixed(2)+' s', X(uniq[k]), Y(0)-12);
      }
    }

    // 状态文字
    var st = document.getElementById('p3Status');
    if (x0 <= 0.001){
      st.className = 'p3-status zero';
      st.textContent = 'x₀ = 0：出发时就在同一位置。A 速度快，先超过 B，之后 B 反超——只有一次「重新相遇」。';
    } else if (x0 < 24 - 1e-6){
      st.className = 'p3-status two';
      st.textContent = '0 < x₀ = '+x0.toFixed(1)+' m < 24 m：曲线两次穿过零线 ⇒ 相遇两次（t = '
        + ((12-Math.sqrt(disc))/3).toFixed(2) + ' s 和 t = ' + ((12+Math.sqrt(disc))/3).toFixed(2) + ' s）。';
    } else if (x0 < 24 + 1e-6){
      st.className = 'p3-status one';
      st.textContent = 'x₀ = 24 m：曲线最小值恰好为 0（在 t = 4 s 相切）⇒ 只能勉强碰到一次。';
    } else {
      st.className = 'p3-status zero';
      st.textContent = 'x₀ = '+x0.toFixed(1)+' m > 24 m：曲线始终在零线之上，最小值 '+ (x0-24).toFixed(1)
        +' m > 0 ⇒ A 追不上 B，不会相遇。';
    }
    document.getElementById('x0Val').textContent = x0.toFixed(1);
  }

  /* ================= 总渲染 ================= */
  function render(){
    updateScene(state.t);
    updateReadouts(state.t);
    drawXT();
    drawVT();
    drawPart3();
  }

  /* ================= 步骤 ================= */
