  function applyStep(i){
    if (i < 0) i = 0;
    if (i >= STEPS.length) i = STEPS.length - 1;
    state.step = i;
    var s = STEPS[i];
    document.getElementById('stepTitle').innerHTML = s.title;
    document.getElementById('stepBody').innerHTML = s.body;
    document.getElementById('stepFormula').innerHTML = s.formula;
    document.getElementById('stepLabel').textContent = (i+1) + ' / ' + STEPS.length;
    document.getElementById('prevStep').disabled = (i === 0);
    document.getElementById('nextStep').disabled = (i === STEPS.length-1);
    state.t = s.t;
    syncSlider();
    render();
  }

  /* ================= 交互 ================= */
  var slider = document.getElementById('tSlider');
  var playBtn = document.getElementById('playBtn');

  function syncSlider(){ slider.value = state.t; }

  function setPlaying(v){
    state.playing = v;
    playBtn.textContent = v ? '暂停' : '播放';
    playBtn.classList.toggle('primary', !v);
    if (v) lastTs = 0;
  }

  slider.addEventListener('input', function(){
    state.t = parseFloat(slider.value);
    setPlaying(false);
    render();
  });

  playBtn.addEventListener('click', function(){
    if (state.playing){ setPlaying(false); return; }
    if (state.t >= T_MAX - 0.01) state.t = 0;
    setPlaying(true);
  });

  document.getElementById('resetBtn').addEventListener('click', function(){
    setPlaying(false);
    state.t = 0;
    syncSlider();
    render();
  });

  document.getElementById('prevStep').addEventListener('click', function(){
    applyStep(state.step - 1);
  });
  document.getElementById('nextStep').addEventListener('click', function(){
    applyStep(state.step + 1);
  });

  var x0Slider = document.getElementById('x0Slider');
  x0Slider.addEventListener('input', function(){
    state.x0 = parseFloat(x0Slider.value);
    drawPart3();
  });

  /* ================= 动画循环 ================= */
  var lastTs = 0;
  function loop(ts){
    if (state.playing){
      if (!lastTs) lastTs = ts;
      var dt = (ts - lastTs) / 1000;
      lastTs = ts;
      if (dt > 0.1) dt = 0.1;
      state.t += dt * 1.0;
      if (state.t >= T_MAX){
        state.t = T_MAX;
        setPlaying(false);
      }
      syncSlider();
      render();
    } else {
      lastTs = 0;
    }
    requestAnimationFrame(loop);
  }

  window.addEventListener('resize', function(){
    cache = new WeakMap();
    render();
  });

  /* ================= 启动 ================= */
  buildRoad();
  applyStep(0);
  drawPart3();
  requestAnimationFrame(loop);
})();
</script>
</body>
</html>
